            if observation['action'] == 'cooperate':
                delta += 0.1   # extra reward
            else:
                delta -= 0.1   # extra punishment
        else:  # last action was defect
            # After defecting, be slightly more lenient
            if observation['action'] == 'cooperate':
                delta += 0.05
            else:
                delta += 0.1   # less harsh punishment

    new_rep = (1 - gamma) * current_reputation + gamma * delta
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Base threshold rises slower and caps higher
    base_threshold = min(0.2 + round_num / 80.0, 0.65)

    # Adjustment based on recent personal history (last 5 rounds)
    adjustment = 0.0
    if len(my_history) >= 5:
        recent = my_history[-5:]
        coop_count = sum(1 for d in recent if d['my_action'] == 'cooperate')
        coop_proportion = coop_count / 5.0
        if coop_proportion > 0.6:
            adjustment = -0.15   # more trusting after frequent cooperation
        elif coop_proportion < 0.4:
            adjustment = 0.15    # more cautious after infrequent cooperation
        # else: neutral

    # Extra trust in early rounds to seed cooperation
    if round_num < 10:
        adjustment -= 0.15

    # Slightly more cautious in very late rounds
    if round_num > 25:
        adjustment += 0.1

    threshold = base_threshold + adjustment

    # Always defect if reputation is extremely negative
    if recipient_reputation < -0.8:
        return False

    return recipient_reputation > threshold
